questionvariables.text:
m : rand([2.5, 3, 3.5, 4]);
c : rand([-2, -1.5, -1, 1, 2]);
xp : rand([9, 10, 12, 15]);
yp : m*xp + c;
py1 : max(0, round(m*1 + c + rand([-1,0,1])));
py2 : max(0, round(m*2 + c + rand([-1,0,1])));
py3 : max(0, round(m*3 + c + rand([-1,0,1])));
py4 : max(0, round(m*4 + c + rand([-1,0,1])));
py5 : max(0, round(m*5 + c + rand([-1,0,1])));
py6 : max(0, round(m*6 + c + rand([-1,0,1])));
ymaxw : round(m*6 + c) + 4;
optR1_str : sconcat("Less reliable: ", xp, " m is far outside the data range (1 m to 6 m), so it is an extrapolation.");
RelOpts : [[optR1, true, optR1_str],
           [optR2, false, "Fully reliable: a straight line can be extended to any value of x."],
           [optR3, false, "More reliable: taller walls always give more accurate predictions."],
           [optR4, false, "Unreliable, only because the points do not lie exactly on the line."]];

feedbackvariables.text:
p1x:ans1[1]; p1y:ans1[2]; p2x:ans2[1]; p2y:ans2[2];
dxp : p2x - p1x;
ms : if is(dxp=0) then 1000000 else (p2y-p1y)/dxp;
cs : if is(dxp=0) then 1000000 else p1y - ms*p1x;

p1x:ans1[1]; p1y:ans1[2]; p2x:ans2[1]; p2y:ans2[2];
dxp : p2x - p1x;
ms : if is(dxp=0) then 1000000 else (p2y-p1y)/dxp;
